// EQL unified logout link.
// Replaces MediaWiki's normal logout URL with our unified wiki+forum logout script.
$wgHooks['SkinTemplateNavigation::Universal'][] = function ( $skinTemplate, &$links ) {
    $logoutUrl = 'https://eqlwiki.com/eql_logout.php';

    // Modern skins, including current Vector-style user menu.
    if ( isset( $links['user-menu']['logout'] ) ) {
        $links['user-menu']['logout']['href'] = $logoutUrl;
    }

    // Some skins/menus may expose logout in user-page or other personal areas.
    if ( isset( $links['user-page']['logout'] ) ) {
        $links['user-page']['logout']['href'] = $logoutUrl;
    }

    // Fallback: scan all top-level menu groups for a logout item.
    foreach ( $links as &$menu ) {
        if ( is_array( $menu ) && isset( $menu['logout'] ) && is_array( $menu['logout'] ) ) {
            $menu['logout']['href'] = $logoutUrl;
        }
    }

    return true;
};

