// EQL: Create SMF forum account immediately when a wiki account is created.
$wgHooks['LocalUserCreated'][] = function ( $user, $autocreated ) {
    // Skip auto-created accounts (e.g. CentralAuth, imports).
    if ( $autocreated ) {
        return true;
    }

    global $IP;
    require_once "$IP/bb/smf_create_member.php";

    $ip = RequestContext::getMain()->getRequest()->getIP();

    smf_create_shadow_member(
        $user->getName(),
        (string)$user->getEmail(),
        $ip
    );

    return true;
};

